    'Cortar': ['Cut', 'Cortar'],
    'Dejar pasar las conexiones de esta empresa en esta sesión': ['Let this company\'s connections through in this session', 'Deixar passar as conexões desta empresa nesta sessão'],
    'Volver a cortar las conexiones de esta empresa': ['Cut this company\'s connections again', 'Voltar a cortar as conexões desta empresa'],
    'Conexión vista (dejada pasar)': ['Connection seen (let through)', 'Conexão vista (deixada passar)'],
